#!/usr/bin/env python3
"""Emit one atomic Linux CPUIdle sysfs snapshot as compact JSON."""
import glob
import json
import os
import re
import sys
import time

SCHEMA_VERSION = 1
CPU_ROOT = "/sys/devices/system/cpu"
CPU_RANGE_RE = re.compile(r"^[0-9,-]+$")
STATE_RE = re.compile(r"state([0-9]+)$")


def read_text(path):
    with open(path, "r", encoding="ascii") as handle:
        return handle.read().strip()


def read_int(path):
    value = int(read_text(path), 10)
    if value < 0:
        raise ValueError(f"negative sysfs value: {path}")
    return value


def optional_int(path):
    try:
        return read_int(path)
    except FileNotFoundError:
        return None


def expand_cpu_list(spec):
    if not spec or not CPU_RANGE_RE.fullmatch(spec):
        raise ValueError(f"invalid online CPU list: {spec!r}")
    cpus = set()
    for part in spec.split(","):
        if "-" in part:
            first_text, last_text = part.split("-", 1)
            first, last = int(first_text), int(last_text)
            if last < first:
                raise ValueError(f"descending online CPU range: {part!r}")
            cpus.update(range(first, last + 1))
        else:
            cpus.add(int(part))
    return sorted(cpus)


def read_governor():
    for name in ("current_governor_ro", "current_governor"):
        path = os.path.join(CPU_ROOT, "cpuidle", name)
        try:
            value = read_text(path)
            if value:
                return value
        except FileNotFoundError:
            continue
    raise FileNotFoundError("no CPUIdle current_governor_ro/current_governor")


def collect_state(cpu_id, state_path, cpu_state_count):
    match = STATE_RE.search(state_path)
    if not match:
        raise ValueError(f"invalid CPUIdle state directory: {state_path}")
    state = {
        "cpu_id": cpu_id,
        "cpu_state_count": cpu_state_count,
        "state_index": int(match.group(1)),
        "state_name": read_text(os.path.join(state_path, "name")),
        "time_us_total": read_int(os.path.join(state_path, "time")),
        "usage_total": read_int(os.path.join(state_path, "usage")),
        "target_residency_us": read_int(os.path.join(state_path, "residency")),
        "exit_latency_us": read_int(os.path.join(state_path, "latency")),
        "disabled": read_int(os.path.join(state_path, "disable")),
    }
    if state["disabled"] not in (0, 1) or not state["state_name"]:
        raise ValueError(f"invalid state attributes: {state_path}")
    for filename, field in (("above", "above_total"), ("below", "below_total"), ("rejected", "rejected_total")):
        value = optional_int(os.path.join(state_path, filename))
        if value is not None:
            state[field] = value
    return state


def emit(event):
    print(json.dumps(event, separators=(",", ":"), sort_keys=False), flush=True)


def main():
    sample_epoch = int(time.time())
    sample_monotonic_ns = time.monotonic_ns()
    base = {
        "schema_version": SCHEMA_VERSION,
        "record_type": "snapshot",
        "sample_epoch": sample_epoch,
    }
    try:
        boot_id = read_text("/proc/sys/kernel/random/boot_id")
        online_before = read_text(os.path.join(CPU_ROOT, "online"))
        cpu_ids = expand_cpu_list(online_before)
        driver_before = read_text(os.path.join(CPU_ROOT, "cpuidle", "current_driver"))
        governor_before = read_governor()
        states = []
        for cpu_id in cpu_ids:
            state_paths = sorted(
                glob.glob(os.path.join(CPU_ROOT, f"cpu{cpu_id}", "cpuidle", "state*")),
                key=lambda path: int(STATE_RE.search(path).group(1)) if STATE_RE.search(path) else -1,
            )
            if not state_paths:
                raise FileNotFoundError(f"no CPUIdle states for online cpu{cpu_id}")
            if len({int(STATE_RE.search(path).group(1)) for path in state_paths}) != len(state_paths):
                raise ValueError(f"duplicate CPUIdle state index for cpu{cpu_id}")
            for state_path in state_paths:
                states.append(collect_state(cpu_id, state_path, len(state_paths)))
        online_after = read_text(os.path.join(CPU_ROOT, "online"))
        driver_after = read_text(os.path.join(CPU_ROOT, "cpuidle", "current_driver"))
        governor_after = read_governor()
        if online_before != online_after or driver_before != driver_after or governor_before != governor_after:
            raise RuntimeError("CPUIdle topology, driver, or governor changed during collection")
        if len(states) < len(cpu_ids):
            raise RuntimeError("incomplete CPUIdle state snapshot")
        base.update({
            "collector_status": "ok",
            "snapshot_id": f"{boot_id}:{sample_monotonic_ns}",
            "sample_monotonic_ns": sample_monotonic_ns,
            "boot_id": boot_id,
            "online_cpu_list": online_before,
            "online_cpu_count": len(cpu_ids),
            "current_driver": driver_before,
            "current_governor": governor_before,
            "snapshot_state_count": len(states),
            "states": states,
        })
        emit(base)
        return 0
    except Exception as exc:
        base.update({
            "record_type": "status",
            "collector_status": "error",
            "error_class": type(exc).__name__,
            "error_reason": str(exc)[:256],
        })
        emit(base)
        print(f"CPUIdle collection failed: {type(exc).__name__}: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
